"""Robonix entry point for the fruit_pick skill.

The skill never talks to hardware. At activation it asks Atlas for the
configured arm, gripper and camera providers' standard contracts and
connects to them; ROS 2 for the streams, gRPC for the gripper commands.
"""

from __future__ import annotations

import asyncio
import logging
import os

import grpc
import numpy as np

from robonix_api import ATLAS, Deferred, Err, Ok, Skill
from robonix_api.atlas_types import Transport
from robonix_api.lifecycle import resolve_servicer

# Generated by scripts/build.sh: MCP types for this skill's contracts, and the
# gRPC stubs and ROS 2 types of the gripper contracts.
from fruit_pick_mcp import (CancelPickFruit_Request, CancelPickFruit_Response,
                            CaptureBackground_Request, CaptureBackground_Response,
                            GetPickFruitStatus_Request, GetPickFruitStatus_Response,
                            PickFruit_Request, PickFruit_Response)
import gripper_pb2
import robonix_contracts_pb2_grpc as contracts_grpc

from .clients import ArmClient, CameraClient, GripperClient
from .config import SkillConfig
from .runner import Runner

ARM = "robonix/primitive/arm/"
GRIPPER = "robonix/primitive/gripper/"
CAMERA = "robonix/primitive/camera/"
PICK_FRUIT = "robonix/skill/fruit_pick/pick_fruit"
CAPTURE_BACKGROUND = "robonix/skill/fruit_pick/capture_background"
RPC_TIMEOUT_S = 5.0

log = logging.getLogger("fruit_pick")
skill = Skill(id=os.environ.get("RBNX_INSTANCE_NAME", "fruit_pick"),
              namespace="robonix/skill/fruit_pick")
config = None
runner = None
active = False
gripper_rpc = {}


def seconds(stamp):
    return stamp.sec + stamp.nanosec * 1e-9


def gripper_call(leaf, request):
    """Call one gripper RPC; return ``(ok, message)``."""
    stub, method = gripper_rpc[leaf]
    try:
        reply = getattr(stub, method)(request, timeout=RPC_TIMEOUT_S)
    except grpc.RpcError as exc:
        return False, f"{leaf} RPC failed: {exc.code().name}"
    return reply.ok, reply.message


def connect_gripper(caps):
    """Open one channel per gripper RPC and read ``info``; return its max opening width."""
    for leaf, cap in caps.items():
        channel = skill.connect_capability(cap, GRIPPER + leaf, Transport.GRPC)
        _, method, _, base = resolve_servicer(GRIPPER + leaf, contracts_grpc)
        gripper_rpc[leaf] = (getattr(contracts_grpc, base + "Stub")(grpc.insecure_channel(channel.endpoint)),
                             method)
    info = getattr(gripper_rpc["info"][0], gripper_rpc["info"][1])(
        gripper_pb2.GetGripperInfo_Request(), timeout=RPC_TIMEOUT_S)
    if not info.ok or not info.opening_width_range_valid:
        raise RuntimeError(f"the gripper reports no opening width range: {info.message}")
    if not info.grip_without_expected_object_width_supported:
        raise RuntimeError("the gripper cannot grip without an expected object width")
    return info.max_opening_width_m


def wanted():
    """Every contract this skill consumes, as (contract, provider_id, transport)."""
    c = config
    return ([(ARM + leaf, c.arm_provider_id, Transport.ROS2)
             for leaf in ("pos_command", "end_pose", "joint_states")]
            + [(GRIPPER + leaf, c.gripper_provider_id, Transport.GRPC) for leaf in ("info", "open", "grip")]
            + [(GRIPPER + "state", c.gripper_provider_id, Transport.ROS2)]
            + [(CAMERA + leaf, c.camera_provider_id, Transport.ROS2) for leaf in ("rgb", "intrinsics")])


def topic(caps, contract):
    return skill.connect_capability(caps[contract], contract, Transport.ROS2).endpoint


def command_publisher(caps):
    """Publisher on the arm's pos_command; return ``(send_pose, commands_ready)``."""
    from geometry_msgs.msg import Pose as PoseMsg

    pub = skill.create_publisher(ARM + "pos_command", topic=topic(caps, ARM + "pos_command"),
                                 msg_type=PoseMsg, qos="reliable", declare=False)

    def send_pose(pose):
        msg = PoseMsg()
        msg.position.x, msg.position.y, msg.position.z = pose.position
        msg.orientation.x, msg.orientation.y, msg.orientation.z, msg.orientation.w = pose.orientation
        pub.publish(msg)

    return send_pose, lambda: pub.get_subscription_count() > 0


def subscribe(caps, arm, gripper, camera):
    """Feed the clients from the providers' topics."""
    from geometry_msgs.msg import Pose as PoseMsg
    from gripper.msg import GripperState
    from sensor_msgs.msg import CameraInfo, Image, JointState

    def on_end_pose(msg):
        p, q = msg.position, msg.orientation
        arm.on_end_pose((p.x, p.y, p.z), (q.x, q.y, q.z, q.w))

    def on_state(msg):
        gripper.on_state(seconds(msg.stamp), msg.motion_state, msg.grasp_state,
                         msg.opening_width_m if msg.opening_width_valid else None)

    def on_image(msg):
        if msg.encoding != "mono8":
            log.warning("ignoring a %s frame; this skill reads mono8", msg.encoding)
            return
        gray = np.frombuffer(bytes(msg.data), np.uint8).reshape(msg.height, msg.step)[:, :msg.width]
        camera.on_image(seconds(msg.header.stamp), gray)

    subs = ((ARM + "end_pose", PoseMsg, on_end_pose, "reliable"),
            (ARM + "joint_states", JointState, lambda m: arm.on_joint_state(list(m.velocity)), "reliable"),
            (GRIPPER + "state", GripperState, on_state, "reliable"),
            (CAMERA + "rgb", Image, on_image, "best_effort"),
            (CAMERA + "intrinsics", CameraInfo,
             lambda m: camera.on_info(m.width, m.height, list(m.k), list(m.d)), "latched"))
    for contract, msg_type, callback, qos in subs:
        skill.create_subscription(contract, topic=topic(caps, contract), msg_type=msg_type,
                                  callback=callback, qos=qos, declare=False)


@skill.on_init
def init(cfg):
    """Validate the config; no connections yet."""
    global config
    try:
        config = SkillConfig.parse(cfg)
    except ValueError as exc:
        return Err(f"invalid fruit_pick config: {exc}")
    log.info("arm %s, gripper %s, camera %s; destinations %s", config.arm_provider_id,
             config.gripper_provider_id, config.camera_provider_id, sorted(config.locations))
    return Ok()


@skill.on_activate
def activate():
    """Connect to every consumed contract; Deferred while one is not offered yet."""
    global runner, active
    if runner is not None:
        active = True
        return Ok()
    caps = {contract: ATLAS.find_capability(contract_id=contract, transport=transport, provider_id=provider)
            for contract, provider, transport in wanted()}
    missing = [c for c, found in caps.items() if len(found) != 1]
    if missing:
        return Deferred(f"waiting for {', '.join(missing)} (pos_command needs motion_enabled on the arm)")
    caps = {contract: found[0] for contract, found in caps.items()}
    try:
        width = connect_gripper({leaf: caps[GRIPPER + leaf] for leaf in ("info", "open", "grip")})
        arm = ArmClient(config, *command_publisher(caps))
        gripper = GripperClient(config, lambda: gripper_call("open", gripper_pb2.Open_Request()),
                                lambda: gripper_call("grip", gripper_pb2.Grip_Request()), width)
        camera = CameraClient(config)
        subscribe(caps, arm, gripper, camera)
        runner = Runner(config, arm, gripper, camera,
                        skill.pkg_root / "rbnx-build" / "data" / f"{skill.id}-background.png")
    except Exception as exc:
        return Err(f"cannot connect to the providers: {exc}")
    active = True
    log.info("connected; open jaws %.0f mm apart", width * 1000)
    return Ok()


@skill.on_deactivate
def deactivate():
    """Cancel the active run and wait for its worker to stop issuing commands."""
    global active
    active = False
    if runner is not None and not runner.cancel_all(timeout_s=5.0):
        return Err("the pick_fruit worker did not stop within 5 s")
    return Ok()


@skill.on_shutdown
def shutdown():
    return deactivate()


def require_active():
    if not active or runner is None:
        raise RuntimeError("fruit_pick is not active")


@skill.mcp(PICK_FRUIT)
def pick_fruit(req: PickFruit_Request) -> PickFruit_Response:
    """Look at the table from the home pose, pick the fruit nearest the middle of
    the view, put it at `destination` (a configured location name, or empty to
    put it back where it was) and return home. Fruit is told apart from the
    table by shape and size, not by kind. Needs capture_background first and
    the arm at home. Returns a run_id immediately."""
    require_active()
    try:
        run_id = runner.start(req.destination.strip())
    except ValueError as exc:
        raise RuntimeError(str(exc)) from exc
    return PickFruit_Response(run_id=run_id, detail="looking for a fruit to pick")


@skill.mcp(f"{PICK_FRUIT}/status")
def pick_fruit_status(req: GetPickFruitStatus_Request) -> GetPickFruitStatus_Response:
    """Read the state of a pick_fruit run."""
    require_active()
    try:
        state, detail = runner.status(req.run_id)
    except KeyError:
        raise RuntimeError(f"unknown pick_fruit run: {req.run_id}") from None
    return GetPickFruitStatus_Response(state=state, detail=detail)


@skill.mcp(f"{PICK_FRUIT}/cancel")
def pick_fruit_cancel(req: CancelPickFruit_Request) -> CancelPickFruit_Response:
    """Cancel a pick_fruit run; the arm finishes its current motion."""
    require_active()
    try:
        running = runner.cancel(req.run_id)
    except KeyError:
        raise RuntimeError(f"unknown pick_fruit run: {req.run_id}") from None
    return CancelPickFruit_Response(accepted=True,
                                    detail="cancel requested" if running else "run already finished")


@skill.mcp(CAPTURE_BACKGROUND)
async def capture_background(req: CaptureBackground_Request) -> CaptureBackground_Response:
    """Photograph the empty table from the home pose as the reference that fruit
    is found against. Clear the table first. Repeat after the table, lighting or
    camera exposure changes. The arm must be near home."""
    _ = req
    require_active()
    try:
        # It moves the arm for up to a minute; keep the MCP event loop free meanwhile.
        detail = await asyncio.to_thread(runner.capture_background)
    except Exception as exc:
        raise RuntimeError(f"capture failed: {exc}") from exc
    return CaptureBackground_Response(detail=detail)


if __name__ == "__main__":
    skill.run()
